module BsdBinaryFullAdder(input_a, input_b, input_c, sum_out, carry_out);
  input input_a;
  wire input_a;
  input input_b;
  wire input_b;
  input input_c;
  wire input_c;
  output sum_out;
  wire sum_out;
  output carry_out;
  wire carry_out;
  wire and1_sig;
  wire and2_sig;
  wire and3_sig;
  wire xor1_sig;
  Gate0 g_and1 (
    .in1(input_a),
    .in2(input_b),
    .out(and1_sig)
  );
  Gate0 g_and2 (
    .in1(input_a),
    .in2(input_c),
    .out(and2_sig)
  );
  Gate0 g_and3 (
    .in1(input_b),
    .in2(input_c),
    .out(and3_sig)
  );
  Gate3Or g_or1 (
    .in1(and1_sig),
    .in2(and2_sig),
    .in3(and3_sig),
    .out(carry_out)
  );
  Gate g_xor1 (
    .in1(input_a),
    .in2(input_b),
    .out(xor1_sig)
  );
  Gate g_xor2 (
    .in1(xor1_sig),
    .in2(input_c),
    .out(sum_out)
  );
endmodule

module Gate(in1, in2, out);
  input in1;
  wire in1;
  input in2;
  wire in2;
  output out;
  wire out;
  XOR2_X1 _0_ (
    .A(in1),
    .B(in2),
    .Z(out)
  );
endmodule

module Gate0(in1, in2, out);
  input in1;
  wire in1;
  input in2;
  wire in2;
  output out;
  wire out;
  AND2_X1 _0_ (
    .A1(in1),
    .A2(in2),
    .ZN(out)
  );
endmodule

module Gate3Or(in1, in2, in3, out);
  input in1;
  wire in1;
  input in2;
  wire in2;
  input in3;
  wire in3;
  output out;
  wire out;
  OR3_X1 _0_ (
    .A1(in3),
    .A2(in1),
    .A3(in2),
    .ZN(out)
  );
endmodule
